package com.hms.queue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.hms.appointments.*; import com.hms.doctors.*; import com.hms.tenancy.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class QueueTokenControllerTests {
 @Autowired MockMvc mockMvc; @Autowired TenantRepository tenants; @Autowired DoctorRepository doctors; @Autowired AppointmentRepository appointments; @Autowired QueueTokenRepository tokens; private Doctor doctor;
 @BeforeEach void setUp(){tokens.deleteAll();appointments.deleteAll();doctors.deleteAll();tenants.deleteAll();Tenant t=tenants.save(new Tenant(UUID.randomUUID(),"city-care","City Care Hospital",null,TenantStatus.ACTIVE,null,null));doctor=doctors.save(new Doctor(t.getId(),new CreateDoctorRequest("Dr. Rao","Cardiology",null,null,5,null,null,true,Set.of())));}
 @Test void createsAndPrioritizesCheckedInToken() throws Exception {String body="{\"fullName\":\"Ravi Kumar\",\"phone\":\"+919000000000\",\"doctorId\":\""+doctor.getId()+"\",\"startsAt\":\"2026-09-28T09:00:00Z\",\"endsAt\":\"2026-09-28T09:20:00Z\",\"source\":\"STAFF\"}";String json=mockMvc.perform(post("/api/hospitals/city-care/appointments").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();String appointmentId=com.jayway.jsonpath.JsonPath.read(json,"$.id");mockMvc.perform(patch("/api/hospitals/city-care/appointments/"+appointmentId+"/status").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"CONFIRMED\"}")).andExpect(status().isOk());mockMvc.perform(patch("/api/hospitals/city-care/appointments/"+appointmentId+"/status").contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"CHECKED_IN\"}")).andExpect(status().isOk());String token=mockMvc.perform(post("/api/hospitals/city-care/queue/appointments/"+appointmentId+"/token")).andExpect(status().isCreated()).andExpect(jsonPath("$.tokenNumber").value(1)).andReturn().getResponse().getContentAsString();String tokenId=com.jayway.jsonpath.JsonPath.read(token,"$.id");mockMvc.perform(patch("/api/hospitals/city-care/queue/"+tokenId+"/priority").contentType(MediaType.APPLICATION_JSON).content("{\"reason\":\"SENIOR_CITIZEN\",\"note\":\"Assistance requested\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.priority").value(true));}
}
